# Taxonomy + multilingual names for the 126 wild animals (south-europe sweep).
# sci: list of (pattern, match, via, rationale). pattern "Genus species" (binomial, optional ssp) or "Genus *" (any species of genus).
# names: local common names (lowercased, accents kept; matcher strips accents) that mean an EXACT match.
# rel: list of (local name, via, rationale) that mean a RELATED match.
E = 'exact'; R = 'related'

T = {}
def add(aid, sci=(), names=(), rel=()):
    T[aid] = {'sci': list(sci), 'names': list(names), 'rel': list(rel)}

